  def lucide_icon(name, css: "w-5 h-5", **attrs)
    inner = ICONS.fetch(name.to_s) { raise ArgumentError, "Ícone Lucide desconhecido: #{name.inspect}" }
    extra = attrs.map { |k, v| %( #{k}="#{v}") }.join
    %(<svg class="#{css} shrink-0" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24"#{extra}>#{inner}</svg>).html_safe
  end
